import re
import shlex

from harness.models import Action, ActionType, RiskDecision, RiskLevel


class RiskClassifier:
    _SHELL_OPERATOR_PATTERN = re.compile(r"[;&|\r\n]")
    _DENY_PATTERNS = (
        "drop database",
        "truncate table",
        ".env",
        ".npmrc",
        ".pypirc",
        "id_rsa",
        "id_ed25519",
        "rm -rf /",
        "del /s",
        "format",
    )
    _REVIEW_PREFIXES = (
        ("git", "push"),
        ("pip", "install"),
        ("npm", "install"),
        ("poetry", "add"),
        ("curl",),
        ("wget",),
        ("uvicorn",),
        ("python", "-m", "http.server"),
    )
    _ALLOW_PREFIXES = (
        ("pytest",),
        ("python", "-m", "pytest"),
        ("ruff",),
        ("git", "status"),
        ("git", "diff"),
    )

    def classify(self, action: Action) -> RiskDecision:
        if action.type != ActionType.RUN_COMMAND:
            return RiskDecision(level=RiskLevel.ALLOW, reasons=["non-command action"])

        command = action.payload.get("command", "")
        if not isinstance(command, str):
            return RiskDecision(level=RiskLevel.ALLOW, reasons=["command is not a string"])

        parts = [part.lower() for part in shlex.split(command, posix=False)]
        normalized = " ".join(parts)

        if any(pattern in normalized for pattern in self._DENY_PATTERNS):
            return RiskDecision(level=RiskLevel.DENY, reasons=["command matches a deny pattern"])

        if self._SHELL_OPERATOR_PATTERN.search(command):
            return RiskDecision(
                level=RiskLevel.REVIEW,
                reasons=["composite shell command requires review"],
            )

        if "--host 0.0.0.0" in normalized or self._starts_with(parts, self._REVIEW_PREFIXES):
            return RiskDecision(level=RiskLevel.REVIEW, reasons=["command requires review"])

        if self._starts_with(parts, self._ALLOW_PREFIXES):
            return RiskDecision(level=RiskLevel.ALLOW, reasons=["command is explicitly allowed"])

        return RiskDecision(level=RiskLevel.ALLOW, reasons=["command has no elevated risk pattern"])

    @staticmethod
    def _starts_with(parts: list[str], prefixes: tuple[tuple[str, ...], ...]) -> bool:
        return any(tuple(parts[: len(prefix)]) == prefix for prefix in prefixes)

from pathlib import Path

from harness.models import Action, ActionType, RiskDecision, RiskLevel


class PathFenceError(ValueError):
    """Raised when an action does not contain a usable path."""


class PathFence:
    _SENSITIVE_NAMES = {".env", ".env.local", ".npmrc", ".pypirc", "id_rsa", "id_ed25519"}

    def __init__(self, workspace_root: Path | str):
        self.workspace_root = Path(workspace_root).resolve(strict=False)

    def resolve(self, candidate: Path | str) -> Path:
        return Path(candidate).resolve(strict=False) if Path(candidate).is_absolute() else (
            self.workspace_root / candidate
        ).resolve(strict=False)

    def check_action(self, action: Action) -> RiskDecision:
        if action.type not in {ActionType.READ_FILE, ActionType.WRITE_FILE}:
            return RiskDecision(
                level=RiskLevel.DENY,
                reasons=["unsupported action type for path fence"],
            )

        candidate = action.payload.get("path")
        if not isinstance(candidate, (Path, str)):
            raise PathFenceError("action payload must contain a path")

        resolved = self.resolve(candidate)
        try:
            resolved.relative_to(self.workspace_root)
        except ValueError:
            return RiskDecision(level=RiskLevel.DENY, reasons=["path is outside workspace"])

        if resolved.name.casefold() in self._SENSITIVE_NAMES:
            return RiskDecision(
                level=RiskLevel.DENY,
                reasons=["path is a sensitive credential file"],
            )

        try:
            relative = resolved.relative_to(self.workspace_root)
        except ValueError:
            return RiskDecision(level=RiskLevel.DENY, reasons=["path is outside workspace"])
        if ".git" in relative.parts:
            return RiskDecision(level=RiskLevel.REVIEW, reasons=["path is git metadata"])

        return RiskDecision(level=RiskLevel.ALLOW, reasons=["path is inside workspace"])

